mapper.select:
SELECT d.id AS deptId, IFNULL(d.dept_name, '未分配部门') AS deptName, COUNT(DISTINCT s.employee_id) AS employeeCount, IFNULL(SUM(s.checkin_count), 0) AS checkinCount, SUM(CASE WHEN s.status = 'NORMAL' THEN 1 ELSE 0 END) AS normalDays, SUM(CASE WHEN s.status = 'LATE' THEN 1 ELSE 0 END) AS lateDays, SUM(CASE WHEN s.status = 'EARLY' THEN 1 ELSE 0 END) AS earlyDays, SUM(CASE WHEN s.status = 'ABSENT' THEN 1 ELSE 0 END) AS absentDays, IFNULL(ROUND(AVG(CASE WHEN s.work_minutes > 0 THEN s.work_minutes END)), 0) AS avgWorkMinutes, IFNULL(ROUND(SUM(CASE WHEN s.status IN ('NORMAL', 'LATE', 'EARLY') THEN 1 ELSE 0 END) * 100.0 / NULLIF(SUM(CASE WHEN s.status <> 'REST' THEN 1 ELSE 0 END), 0), 1), 0) AS attendanceRate FROM att_daily_stat s JOIN hr_employee e ON e.id = s.employee_id LEFT JOIN org_department d ON d.id = e.dept_id
s.stat_date BETWEEN #{dateFrom} AND #{dateTo} AND e.dept_id = #{deptId} AND s.employee_id = #{employeeId}
GROUP BY d.id, d.dept_name ORDER BY checkinCount DESC

SELECT p.id AS placeId, p.place_name AS placeName, HOUR(r.checkin_time) AS hour, COUNT(*) AS count FROM att_record r JOIN biz_place p ON p.id = r.place_id JOIN hr_employee e ON e.id = r.employee_id
r.checkin_time >= #{dateFrom} AND r.checkin_time < DATE_ADD(#{dateTo}, INTERVAL 1 DAY) AND r.place_id = #{placeId} AND e.dept_id = #{deptId} AND r.employee_id = #{employeeId}
GROUP BY p.id, p.place_name, HOUR(r.checkin_time) ORDER BY p.id, hour

SELECT p.id AS placeId, p.place_name AS placeName, -1 AS hour, COUNT(*) AS count FROM att_record r JOIN biz_place p ON p.id = r.place_id JOIN hr_employee e ON e.id = r.employee_id
r.checkin_time >= #{dateFrom} AND r.checkin_time < DATE_ADD(#{dateTo}, INTERVAL 1 DAY) AND e.dept_id = #{deptId} AND r.employee_id = #{employeeId}
GROUP BY p.id, p.place_name ORDER BY count DESC
